<article class="dashboard-enter bg-white rounded-xl border border-slate-200 shadow-sm min-w-0 overflow-hidden">
    <div class="px-3 pt-3 pb-2"><h2 class="text-sm font-bold text-slate-900"><?= esc($heading) ?></h2><p class="text-[10px] text-slate-500 mt-0.5">Outstanding at <?= esc($closingDate) ?> · overdue first, then largest balances</p></div>
    <div class="overflow-x-auto"><table class="w-full text-left text-xs"><thead class="bg-brand-50 text-slate-500 text-[10px]"><tr><th class="px-3 py-2"><?= $type==='invoice'?'Customer':'Supplier' ?></th><th class="px-3 py-2"><?= $type==='invoice'?'Invoice':'Bill' ?></th><th class="px-3 py-2">Due date</th><th class="px-3 py-2 text-right">Balance</th><th class="px-3 py-2">Status</th></tr></thead><tbody class="divide-y divide-slate-100">
        <?php foreach ($rows as $row): ?><tr class="hover:bg-slate-50"><td class="px-3 py-2 font-medium"><?= esc($row['party']??'Unassigned') ?></td><td class="px-3 py-2 font-mono text-[10px]"><?= esc($row[$type==='invoice'?'invoice_no':'bill_no']?:'#'.$row['id']) ?></td><td class="px-3 py-2 whitespace-nowrap text-slate-500"><?= esc($row['due_date']?:'Not set') ?></td><td class="px-3 py-2 text-right tabular-nums font-semibold <?= $row['overdue']?'text-rose-600':'' ?>">$<?= number_format($row['due'],2) ?></td><td class="px-3 py-2"><span class="rounded-md px-1.5 py-0.5 text-[10px] font-semibold <?= $row['overdue']?'bg-rose-50 text-rose-700':($row['payment_status']==='Partial'?'bg-brand-50 text-brand-700':'bg-amber-50 text-amber-700') ?>"><?= esc($row['payment_status']) ?></span></td></tr><?php endforeach; ?>
        <?php if (!$rows): ?><tr><td colspan="5" class="px-3 py-6 text-center text-slate-400">No outstanding <?= $type==='invoice'?'invoices':'bills' ?>.</td></tr><?php endif; ?>
    </tbody></table></div>
